window.AUTH=window.AUTH||{};window.AUTH["20-493"]={"d":"20-493","id":"2021/20-493","n":"Ysleta del Sur Pueblo v. Texas","briefs":[{"k":"petitioner","label":"Brief of petitioners Ysleta del Sur Pueblo, The Tribal Council, The Tribal Governor Michael Silvas or his Successor","date":"2021-12-02","url":"https://www.supremecourt.gov/DocketPDF/20/20-493/203906/20211202160253282_20-493%20-%20YDSP%20Brief%20of%20Petitioners.pdf","side":"pet","n":39},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2021-12-09","url":"https://www.supremecourt.gov/DocketPDF/20/20-493/204680/20211209194855430_20-493tsacUnited%20States.pdf","side":"us","n":81},{"k":"respondent","label":"Brief of respondent Texas","date":"2022-01-10","url":"https://www.supremecourt.gov/DocketPDF/20/20-493/207816/20220110143403443_20-493%20Brief%20for%20Respondent.pdf","side":"res","n":71},{"k":"reply","label":"Reply of petitioners Ysleta del Sur Pueblo, The Tribal Council, The Tribal Governor Michael Silvas or his Successor","date":"2022-02-03","url":"https://www.supremecourt.gov/DocketPDF/20/20-493/213252/20220203164033339_20-493%20-%20YDSP%20Reply%20Brief%20of%20Petitioners.pdf","side":"pet","n":26}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/596us2r45_3d46.pdf","tr":true,"items":[{"t":"case","label":"14 Penn Plaza LLC v. Pyett","cite":"556 U.S. 247","y":2009,"id":"2008/07-581","sc":1,"by":{"0":"45"}},{"t":"case","label":"Ala.-Coushatta Indian Tribe of Tex. v. Mattox","cite":"650 F. Supp. 282","y":1986,"court":"W.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp./650/282/","by":{"0":"6"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"duty to give effect, if possible, to every clause and word of a statute rather than to emasculate an entire section.","cite":"520 U.S. 154, 173"}]},{"t":"case","label":"Bragdon v. Abbott","cite":"524 U.S. 624","y":1998,"id":"1997/97-156","sc":1,"by":{"0":"26, 27"},"q":[{"src":"brief","b":0,"text":"judicial interpretations have settled the meaning of an existing statutory provision, repetition of the same language in a new statute indicates, as a general matter, the intent to incorporate its . . . judicial interpretations as well.","cite":"524 U.S. 624, 645"}]},{"t":"case","label":"Bryan v. Itasca Cnty.","cite":"426 U.S. 373","y":1976,"id":"1975/75-5027","sc":1,"by":{"0":"passim","1":"5, 6, 16, 17, 31","2":"passim","3":"6"},"q":[{"src":"brief","b":1,"text":"rules of decision [applied by state courts] to decide [private] disputes.","cite":"426 U.S. 373, 384"},{"src":"brief","b":2,"text":"was with the problem of lawlessness on certain Indian reservations, and the absence of adequate tribal institutions for law enforcement.","cite":"426 U.S. at 379"},{"src":"brief","b":2,"text":"lack of adequate Indian forums for resolving private legal disputes between reservation Indians, and between Indians and other private citizens,","cite":"426 U.S. at 383"},{"src":"brief","b":3,"text":"cogent proof that Congress knew well how to express its intent directly when that intent was to subject reservation Indians to the full sweep of state [gaming] laws.","cite":"426 U.S. 373, 389"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"the problem of lawlessness on certain Indian reservations.","cite":"426 U. S., at 379"},{"src":"argument","who":"Mr. Martin","text":"It's the Bryan versus Itasca County test. They don't have that regulatory authority. Whereas, in 107(c), in the title alone, it says jurisdiction over enforcement."},{"src":"argument","who":"Justice Sotomayor","text":"-- counsel, why are you relying just on Cabazon? Bryan, in 1976, used the dichotomy of prohibited versus regulatory, correct?"},{"src":"argument","who":"Mr. Yang","text":"Public -- Cabazon applied a distinction in Bryan. Bryan understood that there's an important principle at stake here. You need to preserve tribal sovereignty and tribal government and that if you allow state regulatory power on tribal lands, you would destroy tribal sovereignty."}]},{"t":"case","label":"California v. Cabazon Band of Mission Indians","cite":"480 U.S. 202","y":1987,"id":"1986/85-1708","sc":1,"by":{"0":"passim","1":"passim","2":"passim","3":"passim"},"q":[{"src":"brief","b":0,"text":"but if the state law generally permits the conduct at issue, subject to regulation, it must be classified as civil/regulatory.","cite":"480 U.S. at 209"},{"src":"brief","b":2,"text":"And because enforcement of [the Restoration Act] is an exercise of federal rather than state authority, there is no danger of state encroachment on Indian tribal sovereignty.","cite":"480 U.S. at 213"},{"src":"brief","b":3,"text":"there is no danger of state encroachment on Indian tribal sovereignty.","cite":"480 U.S. at 213"},{"src":"argument","who":"Mr. Yang","text":"Cabazon was a provision in California law that only allowed charities to operate bingo and that set a limit of $250, and the Court said, you know what, that is regulating bingo, it is not prohibiting bingo."},{"src":"argument","who":"Ms. Pettit","text":"And it may be useful to answer your question to distinguish this from the facts in California's instance in Cabazon Band, where they generally permitted gambling except that which we prohibited."}]},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"by":{"0":"46"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"so that effect is given to all provisions, so that no part will be inoperative or superfuous, void or insignifcant.","cite":"556 U. S. 303, 314"}]},{"t":"case","label":"Dep’t of Rev. of Or. v. ACF Indus., Inc.","cite":"510 U.S. 332","y":1994,"id":"1993/92-74","sc":1,"by":{"0":"31"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"by":{"0":"34, 36","3":"21"},"q":[{"src":"brief","b":0,"text":"When confronted with two Acts of Congress allegedly touching on the same topic, this Court is not at ‘liberty to pick and choose among congressional enactments’ and must instead strive ‘to give effect to both.’","cite":"138 S. Ct. 1612, 1624"},{"src":"brief","b":0,"text":"[a] party seeking to suggest that two statutes cannot be harmonized, and that one displaces the other, bears the heavy burden of showing ‘a clearly expressed congressional intention’ that such a result should follow.","cite":"138 S. Ct. at 1624"},{"src":"brief","b":3,"text":"[a] party seeking to suggest that two statutes cannot be harmonized, and that one displaces the other, bears the heavy burden of showing ‘a clearly expressed congressional intention’ that such a result should follow.","cite":"138 S. Ct. 1612, 1624"}]},{"t":"case","label":"Lagos v. United States","cite":"138 S. Ct. 1684","y":2018,"id":"2017/16-1519","sc":1,"by":{"0":"30"}},{"t":"case","label":"Life Techs. Corp. v. Promega Corp.","cite":"137 S. Ct. 734","y":2017,"id":"2016/14-1538","sc":1,"by":{"0":"30"}},{"t":"case","label":"Liteky v. United States","cite":"510 U.S. 540","y":1994,"id":"1993/92-6921","sc":1,"by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"would cause the statute, in a significant sense, to contradict itself.","cite":"510 U.S. 540, 552–53"}]},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"by":{"0":"26, 32"}},{"t":"case","label":"Mashantucket Pequot Tribe v. Connecticut","cite":"913 F.2d 1024","y":1990,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/913/1024/","by":{"0":"14"}},{"t":"case","label":"Massachusetts v. Wampanoag Tribe of Gay Head (Aquinnah)","cite":"853 F.3d 618","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/853/618/","by":{"0":"48"},"q":[{"src":"argument","who":"Justice Gorsuch","text":"And that -- that hinges on whether we -- we -- we agree with your reading of the statute and the enactment the same day involving the tribe in Massachusetts, right?"}]},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith, Inc. v. Curran","cite":"456 U.S. 353","y":1982,"id":"1981/80-203","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"[W]here, as here, Congress adopts a new law incorporating sections of a prior law, Congress normally can be presumed to have had knowledge of the interpretation given to the incorporated law, at least insofar as it affects the new statute.","cite":"456 U.S. 353, 382 n.66"}]},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"by":{"0":"37","1":"26, 30, 31","2":"45"},"q":[{"src":"brief","b":1,"text":"[T]o abrogate [tribal] immunity, Congress must ‘unequivocally’ express that purpose.","cite":"572 U.S. 782, 790"},{"src":"brief","b":1,"text":"tribal [sovereign] immunity does not bar [a State’s] suit for injunctive relief against * * * tribal officers[] responsible for unlawful conduct.","cite":"572 U.S. at 796"}]},{"t":"case","label":"Montana v. Blackfeet Tribe of Indians","cite":"471 U.S. 759","y":1985,"id":"1984/83-2161","sc":1,"by":{"0":"37","1":"31"},"q":[{"src":"brief","b":0,"text":"be construed liberally in favor of the Indians, with ambiguous provisions interpreted to their benefit.","cite":"471 U.S. 759, 766"},{"src":"brief","b":1,"text":"statutes are to be construed liberally in favor of the Indians, with ambiguous provisions interpreted to their benefit.","cite":"471 U.S. 759, 766"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"statutes are to be construed liberally in favor of the Indians, with ambiguous provisions interpreted to their beneft.","cite":"471 U. S. 759, 766"}]},{"t":"case","label":"POM Wonderful LLC v. Coca-Cola Co.","cite":"573 U.S. 102","y":2014,"id":"2013/12-761","sc":1,"by":{"0":"34"}},{"t":"case","label":"Seminole Tribe of Fla. v. Butterworth","cite":"658 F.2d 310","y":1981,"court":"5th Cir. Unit B","url":"https://www.courtlistener.com/c/F.2d/658/310/","by":{"0":"10, 50, 51, 52","1":"6"},"q":[{"src":"argument","who":"Justice Sotomayor","text":"The Winnepaug passed the very same day and it used regulations, those laws and regulations which prohibit or regulate. The Seminole, also passed in 1987, also talked about prohibiting and regulating. Correct?"}]},{"t":"case","label":"Shaughnessy v. Pedreiro","cite":"349 U.S. 48","y":1955,"id":"scdb/1954-069","sc":1,"by":{"0":"45"}},{"t":"case","label":"Stokeling v. United States","cite":"139 S. Ct. 544","y":2019,"id":"2018/17-5554","sc":1,"by":{"0":"47","1":"21","3":"3"}},{"t":"case","label":"Texas v. Ysleta del Sur Pueblo","cite":"220 F. Supp. 2d 668","y":2001,"court":"W.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/220/668/","by":{"0":"17","2":"8, 10, 15"},"q":[{"src":"brief","b":0,"text":"transformed the Court into a quasiregulatory body overseeing and monitoring the minutiae of the Pueblo Defendants’ gaming-related conduct.","cite":"220 F. Supp. 2d 668"},{"src":"brief","b":2,"text":"simultaneously transferred responsibility for the Indians to the State of Texas.","cite":"220 F. Supp. 2d 668, 676"},{"src":"brief","b":2,"text":"subject to all obligations and duties under the laws of the State of Texas,","cite":"220 F. Supp. 2d at 676"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"did not provide adequate protection against high stakes gaming operations on the Tribe's reservation.","cite":"220 F. Supp. 2d 668, 677"}]},{"t":"case","label":"Texas v. Ysleta del Sur Pueblo","cite":"514 U.S. 1016","y":1995,"url":"https://supreme.justia.com/cases/federal/us/514/1016/","sc":1,"by":{"0":"17"},"q":[{"src":"brief","b":0,"text":"since the state has no regulatory, civil or criminal jurisdiction over gaming on Tribal lands.","cite":"514 U.S. 1016"}]},{"t":"case","label":"Texas v. Ysleta del Sur Pueblo","cite":"2009 WL 10679419","y":2009,"court":"W.D. Tex. Aug. 4","by":{"0":"17","3":"17, 19, 24"}},{"t":"case","label":"Texas v. Ysleta del Sur Pueblo","cite":"2016 WL 3039991","y":2016,"court":"W.D. Tex. May 27","by":{"0":"17","1":"27","2":"15, 31, 32","3":"17"},"q":[{"src":"brief","b":0,"text":"transformed the Court into a quasiregulatory body overseeing and monitoring the minutiae of the Pueblo Defendants’ gaming-related conduct.","cite":"2016 WL 3039991"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"transformed [it] into a quasi-regulatory body overseeing and monitoring the minutiae of the [Tribe's] gaming-related conduct.","cite":"2016 WL 3039991"}]},{"t":"case","label":"U.S. Dep’t of Energy v. Ohio","cite":"503 U.S. 607","y":1992,"id":"1991/90-1341","sc":1,"by":{"0":"26"}},{"t":"case","label":"United States v. Lopez","cite":"514 U.S. 549","y":1995,"id":"1994/93-1260","sc":1,"by":{"0":"28"}},{"t":"case","label":"United States v. Sisseton-Wahpeton Sioux Tribe","cite":"897 F.2d 358","y":1990,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/897/358/","by":{"0":"14"}},{"t":"case","label":"Wisconsin v. Ho-Chunk Nation","cite":"784 F.3d 1076","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/784/1076/","by":{"0":"14, 47","2":"32"}},{"t":"case","label":"Ysleta del Sur Pueblo v. Texas","cite":"36 F.3d 1325","y":1994,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/36/1325/","by":{"0":"passim","1":"10","2":"passim"},"q":[{"src":"brief","b":1,"text":"Congress—and [petitioner]— intended for Texas’ gaming laws and regulations to operate as surrogate federal law on the Tribe’s reservation in Texas.","cite":"36 F.3d at 1334"},{"src":"brief","b":1,"text":"gambling, lottery or bingo as defined by the laws and administrative regulations of the State of Texas.","cite":"36 F.3d 1325, 1333"},{"src":"brief","b":2,"text":"explicitly stated in two separate provisions . . . that [it] should be considered in light of other federal law.","cite":"36 F.3d at 1335"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"operate as surrogate federal law on the Tribe's reservation.","cite":"36 F. 3d 1325, 1326, 1334"}]},{"t":"case","label":"Ysleta del Sur Pueblo v. Texas","cite":"852 F. Supp. 587","y":1993,"court":"W.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp./852/587/","by":{"0":"14"}},{"t":"usc","label":"18 U.S.C. § 1166","url":"https://www.law.cornell.edu/uscode/text/18/1166","subs":["(d)","(a)","(c)"],"stext":{"head":"§1166. Gambling in Indian country","paras":[[0,"(a) Subject to subsection (c), for purposes of Federal law, all State laws pertaining to the licensing, regulation, or prohibition of gambling, including but not limited to criminal sanctions applicable thereto, shall apply in Indian country in the same manner and to the same extent as such laws apply elsewhere in the State."],[0,"(b) Whoever in Indian country is guilty of any act or omission involving gambling, whether or not conducted or sanctioned by an Indian tribe, which, although not made punishable by any enactment of Congress, would be punishable if committed or omitted within the jurisdiction of the State in which the act or omission occurred, under the laws governing the licensing, regulation, or prohibition of gambling in force at the time of such act or omission, shall be guilty of a like offense and subject to a like punishment."],[0,"(c) For the purpose of this section, the term \"gambling\" does not include—"],[1,"(1) class I gaming or class II gaming regulated by the Indian Gaming Regulatory Act, or"],[1,"(2) class III gaming conducted under a Tribal-State compact approved by the Secretary of the Interior under section 11(d)(8) of the Indian Gaming Regulatory Act that is in effect."],[0,"(d) The United States shall have exclusive jurisdiction over criminal prosecutions of violations of State gambling laws that are made applicable under this section to Indian country, unless an Indian tribe pursuant to a Tribal-State compact approved by the Secretary of the Interior under section 11(d)(8) of the Indian Gaming Regulatory Act, or under any other provision of Federal law, has consented to the transfer to the State of criminal jurisdiction with respect to gambling on the lands of the Indian tribe."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1166?type=usc&year=mostrecent&link-type=html"},"by":{"0":"33","1":"1, 10, 10, 10"},"q":[{"src":"brief","b":1,"text":"transfer [such jurisdiction] to the State.","cite":"18 U.S.C. 1166(d)"}]},{"t":"usc","label":"25 U.S.C. § 731","url":"https://www.law.cornell.edu/uscode/text/25/731","subs":["(2012)"],"by":{"0":"7","1":"2"}},{"t":"law","label":"Pub. L. No. 103-116","url":"https://www.govinfo.gov/link/statute/107/1118","by":{"0":"29"}},{"t":"law","label":"Pub. L. No. 100-228","url":"https://www.govinfo.gov/link/statute/101/1556","by":{"0":"29","1":"32","2":"40"}},{"t":"law","label":"Pub. L. No. 100-95","url":"https://www.govinfo.gov/link/statute/101/704","by":{"0":"29","2":"40","3":"7"}},{"t":"law","label":"Ysleta del Sur Pueblo and Alabama and Coushatta Indian Tribes of Texas Restoration Act, Pub. L. No. 100-89","url":"https://www.govinfo.gov/link/statute/101/666","by":{"0":"passim","1":"23","2":"35"}},{"t":"law","label":"Pub. L. No. 90-287","url":"https://www.govinfo.gov/link/statute/82/93","by":{"0":"6","1":"2","2":"8"}},{"t":"case","label":"Barona Grp. of the Capitan Grande Band of Mission Indians v. Duffy","cite":"694 F.2d 1185","y":1982,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/694/1185/","by":{"1":"6"}},{"t":"case","label":"Cabazon Band of Mission Indians v. County of Riverside","cite":"783 F.2d 900","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/783/900/","by":{"1":"6"}},{"t":"case","label":"Department of Homeland Sec. v. MacLean","cite":"574 U.S. 383","y":2015,"id":"2014/13-894","sc":1,"by":{"1":"23","2":"21, 22"},"q":[{"src":"brief","b":1,"text":"Congress’s choice to say ‘specifically prohibited by law’ rather than ‘specifically prohibited by law, rule, or regulation’ suggests that Congress meant to exclude rules and regulations.","cite":"574 U.S. at 391"}]},{"t":"case","label":"Diamond Game Enters. v. Reno","cite":"230 F.3d 365","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/230/365/","by":{"1":"33"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"by":{"1":"29","3":"10"},"q":[{"src":"brief","b":1,"text":"Few principles of statutory construction are more compelling than the proposition that Congress does not intend sub silentio to enact statutory language that it has earlier discarded in favor of other language.","cite":"480 U.S. 421, 442-443"},{"src":"brief","b":3,"text":"[f ]ew principles of statutory construction are more compelling than the proposition that Congress does not intend sub silentio to enact statutory language that it has earlier discarded in favor of other language.","cite":"480 U.S. 421, 442–43"}]},{"t":"case","label":"Kellogg Brown & Root Servs., Inc. v. United States ex rel. Carter","cite":"575 U.S. 650","y":2015,"id":"2014/12-1497","sc":1,"by":{"1":"21, 22"},"q":[{"src":"brief","b":1,"text":"attach civil penalties to criminal offenses.","cite":"575 U.S. at 659"}]},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"borrowed word in the body of learning from which it was taken.","cite":"342 U.S. 246, 263"}]},{"t":"case","label":"Ryan v. Gonzales","cite":"568 U.S. 57","y":2013,"id":"2012/10-930","sc":1,"by":{"1":"18"}},{"t":"case","label":"State v. Rumfolo","cite":"545 S.W.2d 752","y":1976,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/545/752/","by":{"1":"23"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"by":{"1":"26"}},{"t":"case","label":"Three Affiliated Tribes of the Fort Berthold Reservation v. Wold Eng’g, P. C.","cite":"476 U.S. 877","y":1986,"id":"1985/84-1973","sc":1,"by":{"1":"5, 18"},"q":[{"src":"brief","b":1,"text":"Public Law 280 represents the primary expression of federal policy governing the assumption by States of civil and criminal jurisdiction over the Indian Nations.","cite":"476 U.S. 877, 884"}]},{"t":"case","label":"United States v. Dakota","cite":"796 F.2d 186","y":1986,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/796/186/","by":{"1":"4","2":"26, 27, 29","3":"16"}},{"t":"case","label":"United States v. Farris","cite":"624 F.2d 890","y":1980,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/624/890/","by":{"1":"4"}},{"t":"case","label":"United States v. La Franca","cite":"282 U.S. 568","y":1931,"id":"scdb/1930-097","sc":1,"by":{"1":"21"}},{"t":"case","label":"United States v. Sosseur","cite":"181 F.2d 873","y":1950,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/181/873/","by":{"1":"4"}},{"t":"case","label":"United States v. Wheeler","cite":"435 U.S. 313","y":1978,"id":"1977/76-1629","sc":1,"by":{"1":"30"}},{"t":"case","label":"Virginia Office for Protection & Advocacy v. Stewart","cite":"563 U.S. 247","y":2011,"id":"2010/09-529","sc":1,"by":{"1":"26"}},{"t":"case","label":"Washington v. Confederated Bands & Tribes of Yakima Indian Nation","cite":"439 U.S. 463","y":1979,"id":"1978/77-388","sc":1,"by":{"1":"5, 18"},"q":[{"src":"brief","b":1,"text":"remaining States * * * an option to assume jurisdiction over criminal offenses and civil causes of action in Indian country without consulting with or securing the consent of the [affected] tribes.","cite":"439 U.S. 463, 472-474"},{"src":"brief","b":1,"text":"[t]he basic terms of Pub[lic Law] 280 * * * [we]re well known.","cite":"439 U.S. 463, 471"}]},{"t":"const","label":"Amendment XI","clauses":[["eleventh-amendment","Eleventh Amendment"]],"text":"The Judicial power of the United States shall not be construed to extend to any suit in law or equity, commenced or prosecuted against one of the United States by Citizens of another State, or by Citizens or Subjects of any Foreign State.","by":{"1":"11"}},{"t":"usc","label":"18 U.S.C. § 13","url":"https://www.law.cornell.edu/uscode/text/18/13","by":{"1":"5"}},{"t":"usc","label":"25 U.S.C. § 1321","url":"https://www.law.cornell.edu/uscode/text/25/1321","subs":["(a)(1)"],"stext":{"head":"§1321. Assumption by State of criminal jurisdiction","paras":[[0,"(a) Consent of United States"],[0,"(1) In general"],[1,"The consent of the United States is hereby given to any State not having jurisdiction over criminal offenses committed by or against Indians in the areas of Indian country situated within such State to assume, with the consent of the Indian tribe occupying the particular Indian country or part thereof which could be affected by such assumption, such measure of jurisdiction over any or all of such offenses committed within such Indian country or any part thereof as may be determined by such State to the same extent that such State has jurisdiction over any such offense committed elsewhere within the State, and the criminal laws of such State shall have the same force and effect within such Indian country or part thereof as they have elsewhere within that State."],[0,"(2) Concurrent jurisdiction"],[1,"At the request of an Indian tribe, and after consultation with and consent by the Attorney General, the United States shall accept concurrent jurisdiction to prosecute violations of sections 1152 and 1153 of title 18 within the Indian country of the Indian tribe."],[0,"(b) Alienation, encumbrance, taxation, and use of property; hunting, trapping, or fishing"],[0,"Nothing in this section shall authorize the alienation, encumbrance, or taxation of any real or personal property, including water rights, belonging to any Indian or any Indian tribe, band, or community that is held in trust by the United States or is subject to a restriction against alienation imposed by the United States; or shall authorize regulation of the use of such property in a manner inconsistent with any Federal treaty, agreement, or statute or with any regulation made pursuant thereto; or shall deprive any Indian or any Indian tribe, band, or community of any right, privilege, or immunity afforded under Federal treaty, agreement, or statute with respect to hunting, trapping, or fishing or the control, licensing, or regulation thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/1321?type=usc&year=mostrecent&link-type=html"},"by":{"1":"5, 5, 5, 5"},"q":[{"src":"brief","b":1,"text":"as if the State had assumed jurisdiction","cite":"25 U.S.C. 1321"},{"src":"brief","b":1,"text":"An Act to prescribe penalties for certain acts of violence or intimidation, and for other purposes,","cite":"25 U.S.C. 1321, 1322"}]},{"t":"usc","label":"25 U.S.C. § 1322","url":"https://www.law.cornell.edu/uscode/text/25/1322","subs":["(a)"],"by":{"1":"5, 5, 5"}},{"t":"usc","label":"25 U.S.C. § 1323","url":"https://www.law.cornell.edu/uscode/text/25/1323","subs":["(b)"],"by":{"1":"5"}},{"t":"usc","label":"25 U.S.C. § 2701","url":"https://www.law.cornell.edu/uscode/text/25/2701","subs":["(5)"],"by":{"1":"1, 9, 31"},"q":[{"src":"brief","b":1,"text":"not, as a matter of criminal law and public policy, prohibit such gaming activity,","cite":"25 U.S.C. 2701(5)"}]},{"t":"usc","label":"25 U.S.C. § 2702","url":"https://www.law.cornell.edu/uscode/text/25/2702","subs":["(2)","(3)"],"by":{"1":"33, 33"},"q":[{"src":"brief","b":1,"text":"shield [tribal gaming] from organized crime and other corrupting influences, to ensure that the Indian tribe is the primary beneficiary of the gaming operation, and to assure that gaming is conducted fairly and honestly by both the operator and players.","cite":"25 U.S.C. 2702(2)"}]},{"t":"usc","label":"25 U.S.C. § 2703","url":"https://www.law.cornell.edu/uscode/text/25/2703","subs":["(6)","(7)(A)(i)","(7)(B)","(8)"],"by":{"1":"9, 9, 9, 10, 9"}},{"t":"usc","label":"25 U.S.C. § 2706","url":"https://www.law.cornell.edu/uscode/text/25/2706","subs":["(b)"],"by":{"1":"9, 33"}},{"t":"usc","label":"25 U.S.C. § 2710","url":"https://www.law.cornell.edu/uscode/text/25/2710","subs":["(a)(1)","(a)(2)","(b)(1)","(b)(1)(A)","(b)(2)","(b)(2)(F)(i)","(d)(1)(B)","(d)(1)(C)","(d)(7)(B)(vii)"],"stext":{"head":"§2710. Tribal gaming ordinances","paras":[[0,"(a) Jurisdiction over class I and class II gaming activity"],[0,"(1) Class I gaming on Indian lands is within the exclusive jurisdiction of the Indian tribes and shall not be subject to the provisions of this chapter."],[0,"(2) Any class II gaming on Indian lands shall continue to be within the jurisdiction of the Indian tribes, but shall be subject to the provisions of this chapter."],[0,"(b) Regulation of class II gaming activity; net revenue allocation; audits; contracts"],[0,"(1) An Indian tribe may engage in, or license and regulate, class II gaming on Indian lands within such tribe's jurisdiction, if—"],[1,"(A) such Indian gaming is located within a State that permits such gaming for any purpose by any person, organization or entity (and such gaming is not otherwise specifically prohibited on Indian lands by Federal law), and"],[1,"(B) the governing body of the Indian tribe adopts an ordinance or resolution which is approved by the Chairman."],[0,"A separate license issued by the Indian tribe shall be required for each place, facility, or location on Indian lands at which class II gaming is conducted."],[0,"(2) The Chairman shall approve any tribal ordinance or resolution concerning the conduct, or regulation of class II gaming on the Indian lands within the tribe's jurisdiction if such ordinance or resolution provides that—"],[1,"(A) except as provided in paragraph (4), the Indian tribe will have the sole proprietary interest and responsibility for the conduct of any gaming activity;"],[1,"(B) net revenues from any tribal gaming are not to be used for purposes other than—"],[2,"(i) to fund tribal government operations or programs;"],[2,"(ii) to provide for the general welfare of the Indian tribe and its members;"],[2,"(iii) to promote tribal economic development;"],[2,"(iv) to donate to charitable organizations; or"],[2,"(v) to help fund operations of local government agencies;"],[1,"(C) annual outside audits of the gaming, which may be encompassed within existing independent tribal audit systems, will be provided by the Indian tribe to the Commission;"],[1,"(D) all contracts for supplies, services, or concessions for a contract amount in excess of $25,000 annually (except contracts for professional legal or accounting services) relating to such gaming shall be subject to such independent audits;"],[1,"(E) the construction and maintenance of the gaming facility, and the operation of that gaming is conducted in a manner which adequately protects the environment and the public health and safety; and"],[1,"(F) there is an adequate system which—"],[2,"(i) ensures that background investigations are conducted on the primary management officials and key employees of the gaming enterprise and that oversight of such officials and their management is conducted on an ongoing basis; and"],[2,"(ii) includes—"],[3,"(I) tribal licenses for primary management officials and key employees of the gaming enterprise with prompt notification to the Commission of the issuance of such licenses;"],[3,"(II) a standard whereby any person whose prior activities, criminal record, if any, or reputation, habits and associations pose a threat to the public interest or to the effective regulation of gaming, or create or enhance the dangers of unsuitable, unfair, or illegal practices and methods and activities in the conduct of gaming shall not be eligible for employment; and"],[3,"(III) notification by the Indian tribe to the Commission of the results of such background check before the issuance of any of such licenses."],[0,"(3) Net revenues from any class II gaming activities conducted or licensed by any Indian tribe may be used to make per capita payments to members of the Indian tribe only if—"],[1,"(A) the Indian tribe has prepared a plan to allocate revenues to uses authorized by paragraph (2)(B);"],[1,"(B) the plan is approved by the Secretary as adequate, particularly with respect to uses described in clause (i) or (iii) of paragraph (2)(B);"],[1,"(C) the interests of minors and other legally incompetent persons who are entitled to receive any of the per capita payments are protected and preserved and the per capita payments are disbursed to the parents or legal guardian of such minors or legal incompetents in such amounts as may be necessary for the health, education, or welfare, of the minor or other legally incompetent person under a plan approved by the Secretary and the governing body of the Indian tribe; and"],[1,"(D) the per capita payments are subject to Federal taxation and tribes notify members of such tax liability when payments are made."],[0,"(4)(A) A tribal ordinance or resolution may provide for the licensing or regulation of class II gaming activities owned by any person or entity other than the Indian tribe and conducted on Indian lands, only if the tribal licensing requirements include the requirements described in the subclauses of subparagraph (B)(i) and are at least as restrictive as those established by State law governing similar gaming within the jurisdiction of the State within which such Indian lands are located. No person or entity, other than the Indian tribe, shall be eligible to receive a tribal license to own a class II gaming activity conducted on Indian lands within the jurisdiction of the Indian tribe if such person or entity would not be eligible to receive a State license to conduct the same activity within the jurisdiction of the State."],[0,"(B)(i) The provisions of subparagraph (A) of this paragraph and the provisions of subparagraphs (A) and (B) of paragraph (2) shall not bar the continued operation of an individually owned class II gaming operation that was operating on September 1, 1986, if—"],[1,"(I) such gaming operation is licensed and regulated by an Indian tribe pursuant to an ordinance reviewed and approved by the Commission in accordance with section 2712 of this title,"],[1,"(II) income to the Indian tribe from such gaming is used only for the purposes described in paragraph (2)(B) of this subsection,"],[1,"(III) not less than 60 percent of the net revenues is income to the Indian tribe, and"],[1,"(IV) the owner of such gaming operation pays an appropriate assessment to the National Indian Gaming Commission under section 2717(a)(1) of this title for regulation of such gaming."],[0,"(ii) The exemption from the application of this subsection provided under this subparagraph may not be transferred to any person or entity and shall remain in effect only so long as the gaming activity remains within the same nature and scope as operated on October 17, 1988."],[0,"(iii) Within sixty days of October 17, 1988, the Secretary shall prepare a list of each individually owned gaming operation to which clause (i) applies and shall publish such list in the Federal Register."],[0,"(c) Issuance of gaming license; certificate of self-regulation"],[0,"(1) The Commission may consult with appropriate law enforcement officials concerning gaming licenses issued by an Indian tribe and shall have thirty days to notify the Indian tribe of any objections to issuance of such license."],[0,"(2) If, after the issuance of a gaming license by an Indian tribe, reliable information is received from the Commission indicating that a primary management official or key employee does not meet the standard established under subsection (b)(2)(F)(ii)(II), the Indian tribe shall suspend such license and, after notice and hearing, may revoke such license."],[0,"(3) Any Indian tribe which operates a class II gaming activity and which—"],[1,"(A) has continuously conducted such activity for a period of not less than three years, including at least one year after October 17, 1988; and"],[1,"(B) has otherwise complied with the provisions of this section 1"],[0,"may petition the Commission for a certificate of self-regulation."],[0,"(4) The Commission shall issue a certificate of self-regulation if it determines from available information, and after a hearing if requested by the tribe, that the tribe has—"],[1,"(A) conducted its gaming activity in a manner which—"],[2,"(i) has resulted in an effective and honest accounting of all revenues;"],[2,"(ii) has resulted in a reputation for safe, fair, and honest operation of the activity; and"],[2,"(iii) has been generally free of evidence of criminal or dishonest activity;"],[1,"(B) adopted and is implementing adequate systems for—"],[2,"(i) accounting for all revenues from the activity;"],[2,"(ii) investigation, licensing, and monitoring of all employees of the gaming activity; and"],[2,"(iii) investigation, enforcement and prosecution of violations of its gaming ordinance and regulations; and"],[1,"(C) conducted the operation on a fiscally and economically sound basis."],[0,"(5) During any year in which a tribe has a certificate for self-regulation—"],[1,"(A) the tribe shall not be subject to the provisions of paragraphs (1), (2), (3), and (4) of section 2706(b) of this title;"],[1,"(B) the tribe shall continue to submit an annual independent audit as required by subsection (b)(2)(C) and shall submit to the Commission a complete resume on all employees hired and licensed by the tribe subsequent to the issuance of a certificate of self-regulation; and"],[1,"(C) the Commission may not assess a fee on such activity pursuant to section 2717 of this title in excess of one quarter of 1 per centum of the gross revenue."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/2710?type=usc&year=mostrecent&link-type=html"},"by":{"1":"9, 31, 9, 9, 9, 32, 9, 33, 9, 32, 10, 33, 10, 33"},"q":[{"src":"brief","b":1,"text":"permits such gaming for any purpose by any person, organization or entity.","cite":"25 U.S.C. 2710(b)(1)(A)"},{"src":"brief","b":1,"text":"within a State that permits such gaming for any pur- pose by any person, organization or entity.","cite":"25 U.S.C. 2710(b)(1)(A)"}]},{"t":"usc","label":"25 U.S.C. § 2711","url":"https://www.law.cornell.edu/uscode/text/25/2711","subs":["(a)"],"by":{"1":"33"}},{"t":"usc","label":"25 U.S.C. § 2713","url":"https://www.law.cornell.edu/uscode/text/25/2713","by":{"1":"9"}},{"t":"law","label":"Pub. L. No. 83-280","url":"https://www.govinfo.gov/link/statute/67/588","by":{"1":"5","2":"passim"}},{"t":"usc","label":"18 U.S.C. § 1162","url":"https://www.law.cornell.edu/uscode/text/18/1162","subs":["(a)"],"by":{"1":"5, 16, 17, 5, 5"}},{"t":"usc","label":"28 U.S.C. § 1360","url":"https://www.law.cornell.edu/uscode/text/28/1360","by":{"1":"5, 16"}},{"t":"usc","label":"25 U.S.C. § 1300g-1300g","url":"https://www.law.cornell.edu/uscode/text/25/1300g-1300g","by":{"1":"2"}},{"t":"usc","label":"18 U.S.C. § 38","url":"https://www.law.cornell.edu/uscode/text/18/38","subs":["(c)"],"by":{"1":"22"}},{"t":"usc","label":"18 U.S.C. § 670","url":"https://www.law.cornell.edu/uscode/text/18/670","subs":["(c)"],"by":{"1":"22"}},{"t":"usc","label":"18 U.S.C. § 1034","url":"https://www.law.cornell.edu/uscode/text/18/1034","subs":["(a)"],"by":{"1":"22"}},{"t":"usc","label":"18 U.S.C. § 1955","url":"https://www.law.cornell.edu/uscode/text/18/1955","stext":{"head":"§1955. Prohibition of illegal gambling businesses","paras":[[0,"(a) Whoever conducts, finances, manages, supervises, directs, or owns all or part of an illegal gambling business shall be fined under this title or imprisoned not more than five years, or both."],[0,"(b) As used in this section—"],[1,"(1) \"illegal gambling business\" means a gambling business which—"],[2,"(i) is a violation of the law of a State or political subdivision in which it is conducted;"],[2,"(ii) involves five or more persons who conduct, finance, manage, supervise, direct, or own all or part of such business; and"],[2,"(iii) has been or remains in substantially continuous operation for a period in excess of thirty days or has a gross revenue of $2,000 in any single day."],[1,"(2) \"insured credit union\" shall have the meaning given the term in section 101 of the Federal Credit Union Act (12 U.S.C. 1752)."],[1,"(3) \"insured depository institution\" shall have the meaning given the term in section 3 of the Federal Deposit Insurance Act (12 U.S.C. 1813)."],[1,"(4) \"gambling\" includes but is not limited to pool-selling, bookmaking, maintaining slot machines, roulette wheels or dice tables, and conducting lotteries, policy, bolita or numbers games, or selling chances therein."],[1,"(5) \"savings promotion raffle\" means a contest in which the sole consideration required for a chance of winning designated prizes is obtained by the deposit of a specified amount of money in a savings account or other savings program, where each ticket or entry has an equal chance of being drawn, such contest being subject to regulations that may from time to time be promulgated by the appropriate prudential regulator (as defined in section 1002 of the Consumer Financial Protection Act of 2010 (12 U.S.C. 5481))."],[1,"(6) \"State\" means any State of the United States, the District of Columbia, the Commonwealth of Puerto Rico, and any territory or possession of the United States."],[0,"(c) If five or more persons conduct, finance, manage, supervise, direct, or own all or part of a gambling business and such business operates for two or more successive days, then, for the purpose of obtaining warrants for arrests, interceptions, and other searches and seizures, probable cause that the business receives gross revenue in excess of $2,000 in any single day shall be deemed to have been established."],[0,"(d) Any property, including money, used in violation of the provisions of this section may be seized and forfeited to the United States. All provisions of law relating to the seizures, summary, and judicial forfeiture procedures, and condemnation of vessels, vehicles, merchandise, and baggage for violation of the customs laws; the disposition of such vessels, vehicles, merchandise, and baggage or the proceeds from such sale; the remission or mitigation of such forfeitures; and the compromise of claims and the award of compensation to informers in respect of such forfeitures shall apply to seizures and forfeitures incurred or alleged to have been incurred under the provisions of this section, insofar as applicable and not inconsistent with such provisions. Such duties as are imposed upon the collector of customs or any other person in respect to the seizure and forfeiture of vessels, vehicles, merchandise, and baggage under the customs laws shall be performed with respect to seizures and forfeitures of property used or intended for use in violation of this section by such officers, agents, or other persons as may be designated for that purpose by the Attorney General."],[0,"(e) This section shall not apply to—"],[1,"(1) any bingo game, lottery, or similar game of chance conducted by an organization exempt from tax under paragraph (3) of subsection (c) of section 501 of the Internal Revenue Code of 1986, as amended, if no part of the gross receipts derived from such activity inures to the benefits of any private shareholder, member, or employee of such organization except as compensation for actual expenses incurred by him in the conduct of such activity; or"],[1,"(2) any savings promotion raffle."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1955?type=usc&year=mostrecent&link-type=html"},"by":{"1":"4","3":"14"},"q":[{"src":"brief","b":3,"text":"is a violation of the law of a State or political subdivision in which it is conducted.","cite":"18 U.S.C. § 1955(a)"}]},{"t":"usc","label":"18 U.S.C. § 1964","url":"https://www.law.cornell.edu/uscode/text/18/1964","subs":["(a)"],"by":{"1":"22"}},{"t":"usc","label":"18 U.S.C. § 2239B","url":"https://www.law.cornell.edu/uscode/text/18/2239B","subs":["(b)"],"by":{"1":"22"}},{"t":"usc","label":"18 U.S.C. § 2292","url":"https://www.law.cornell.edu/uscode/text/18/2292","subs":["(a)"],"by":{"1":"22"}},{"t":"usc","label":"25 U.S.C. § 941a","url":"https://www.law.cornell.edu/uscode/text/25/941a","subs":["(10)(2012)","(12)(2012)"],"by":{"1":"32, 32"}},{"t":"usc","label":"25 U.S.C. § 941l","url":"https://www.law.cornell.edu/uscode/text/25/941l","subs":["(2012)"],"by":{"1":"32"}},{"t":"case","label":"Advoc. Health Care Network v. Stapleton","cite":"137 S. Ct. 1652","y":2017,"id":"2016/16-74","sc":1,"by":{"2":"43"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"by":{"2":"29"}},{"t":"case","label":"Barker v. Texas","cite":"12 Tex. 273","y":1854,"url":"https://www.courtlistener.com/c/Tex./12/273/","by":{"2":"3"},"q":[{"src":"brief","b":2,"text":"denounced by the law as an offense against public policy.","cite":"12 Tex. 273, 276"}]},{"t":"case","label":"Bob Jones Univ. v. United States","cite":"461 U.S. 574","y":1983,"id":"1982/81-3","sc":1,"by":{"2":"45"}},{"t":"case","label":"Bostock v. Clayton County","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"by":{"2":"20, 22, 41"}},{"t":"case","label":"BP P.L.C. v. Mayor & City Council of Baltimore","cite":"141 S. Ct. 1532","y":2021,"id":"2020/19-1189","sc":1,"by":{"2":"41"}},{"t":"case","label":"Brackeen v. Haaland","cite":"994 F.3d 249","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/994/249/","by":{"2":"10"}},{"t":"case","label":"Buckhannon Bd. & Care Home, Inc. v. W. Va. Dep’t of Health & Human Res.","cite":"532 U.S. 598","y":2001,"id":"2000/99-1848","sc":1,"by":{"2":"27"}},{"t":"case","label":"Cent. Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"by":{"2":"44"}},{"t":"case","label":"Chickasaw Nation v. United States","cite":"534 U.S. 84","y":2001,"id":"2001/00-507","sc":1,"by":{"2":"34, 37"}},{"t":"case","label":"Chrysler Corp. v. Brown","cite":"441 U.S. 281","y":1979,"id":"1978/77-922","sc":1,"by":{"2":"21, 22"}},{"t":"case","label":"Cases (ctd.): City of Chicago v. Fulton","cite":"141 S. Ct. 585","y":2021,"id":"2020/19-357","sc":1,"by":{"2":"37"}},{"t":"case","label":"City of Fort Worth v. Rylie","cite":"602 S.W.3d 459","y":2020,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/602/459/","by":{"2":"2, 3, 4"},"q":[{"src":"brief","b":2,"text":"For as long as the State of Texas has been the State of Texas, its citizens have elected to constitutionally outlaw most types of ‘lotteries.’","cite":"602 S.W.3d 459, 460"},{"src":"brief","b":2,"text":"Since its ratification in 1876, [the State’s] current constitution has affirmatively required the legislature to ‘pass laws prohibiting’ lotteries.","cite":"602 S.W.3d at 461"}]},{"t":"case","label":"City of Wink v. Griffith Amusement Co.","cite":"100 S.W.2d 695","y":1936,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/100/695/","by":{"2":"3, 5"}},{"t":"case","label":"DeCoteau v. Dist. Cnty. Ct.","cite":"420 U.S. 425","y":1975,"id":"1974/73-1148","sc":1,"by":{"2":"34"}},{"t":"case","label":"Doe v. Mann","cite":"415 F.3d 1038","y":2005,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/415/1038/","by":{"2":"29, 31","3":"17"}},{"t":"case","label":"Env’t Def. v. Duke Energy Corp.","cite":"549 U.S. 561","y":2007,"id":"2006/05-848","sc":1,"by":{"2":"20"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"by":{"2":"34"}},{"t":"case","label":"Fry v. Pliler","cite":"551 U.S. 112","y":2007,"id":"2006/06-5247","sc":1,"by":{"2":"33"}},{"t":"case","label":"Gaming Corp. of Am. v. Dorsey & Whitney","cite":"88 F.3d 536","y":1996,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/88/536/","by":{"2":"33"},"q":[{"src":"argument","who":"Mr. Martin","text":"Section 107 is entitled \"Indian Gaming.\" It is -- it is intended to govern that exact situation in response to Cabazon. And if there's no further questions."}]},{"t":"case","label":"Greater New Orleans Broad. Ass’n, Inc. v. United States","cite":"527 U.S. 173","y":1999,"id":"1998/98-387","sc":1,"by":{"2":"3"},"q":[{"src":"brief","b":2,"text":"private casino gambling is unlawful [in Texas].","cite":"527 U.S. 173, 181"}]},{"t":"case","label":"Herrera v. Wyoming","cite":"139 S. Ct. 1686","y":2019,"id":"2018/17-532","sc":1,"by":{"2":"34"},"q":[{"src":"brief","b":2,"text":"ambiguities [to be] resolved in favor of the Indians,","cite":"139 S. Ct. 1686, 1699"}]},{"t":"case","label":"Cases (ctd.): King v. Burwell","cite":"576 U.S. 473","y":2015,"id":"2014/14-114","sc":1,"by":{"2":"23"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"by":{"2":"23"}},{"t":"case","label":"Lightfoot v. Cendant Mortg. Corp.","cite":"137 S. Ct. 553","y":2017,"id":"2016/14-1055","sc":1,"by":{"2":"28"},"q":[{"src":"brief","b":2,"text":"teaches that if courts have settled the meaning of an existing provision, the enactment of a new provision that mirrors the existing statutory text indicates, as a general matter, that the new provision has that same meaning.","cite":"137 S. Ct. 553, 563"}]},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"2":"38"}},{"t":"case","label":"McGirt v. Oklahoma","cite":"140 S. Ct. 2452","y":2020,"id":"2019/18-9526","sc":1,"by":{"2":"passim"},"q":[{"src":"brief","b":2,"text":"must be considered on their own terms.","cite":"140 S. Ct. at 2479"}]},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"by":{"2":"34"},"q":[{"src":"brief","b":2,"text":"Where there is no clear intention otherwise, a specific statute will not be controlled or nullified by a general one, regardless of the priority of enactment.","cite":"417 U.S. 535, 550-51"}]},{"t":"case","label":"N.Y. State Dep’t of Soc. Servs. v. Dublino","cite":"413 U.S. 405","y":1973,"id":"1972/72-792","sc":1,"by":{"2":"23"}},{"t":"case","label":"Reiter v. Sonotone Corp.","cite":"442 U.S. 330","y":1979,"id":"1978/78-690","sc":1,"by":{"2":"20"},"q":[{"src":"brief","b":2,"text":"give effect, if possible, to every word Congress used.","cite":"442 U.S. 330, 339"}]},{"t":"case","label":"Rice v. Rehner","cite":"463 U.S. 713","y":1983,"id":"1982/82-401","sc":1,"by":{"2":"29"}},{"t":"case","label":"Solem v. Bartlett","cite":"465 U.S. 463","y":1984,"id":"1983/82-1253","sc":1,"by":{"2":"41"}},{"t":"case","label":"State v. Amvets Post No. 80","cite":"541 S.W.2d 481","url":"https://www.courtlistener.com/c/S.W.2d/541/481/","by":{"2":"4"}},{"t":"case","label":"Taniguchi v. Kan Pac. Saipan, Ltd.","cite":"566 U.S. 560","y":2012,"id":"2011/10-1472","sc":1,"by":{"2":"20"}},{"t":"case","label":"Cases (ctd.): Texas v. Alabama-Coushatta Tribe of Tex.","cite":"918 F.3d 440","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/918/440/","by":{"2":"11"}},{"t":"case","label":"Texas v. del Sur Pueblo","cite":"31 F. App’x 835","y":2002,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/31/835/","by":{"2":"15"}},{"t":"case","label":"Texas v. Ysleta del Sur Pueblo","cite":"431 F. App’x 326","y":2011,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/431/326/","by":{"2":"14, 15"}},{"t":"case","label":"Texas v. Ysleta del Sur Pueblo","cite":"2015 WL 1003879","y":2015,"court":"W.D. Tex. Mar. 6","by":{"2":"15"}},{"t":"case","label":"Textron Lycoming Reciprocating Engine Div., Avco Corp. v. United Auto., Aerospace, Agric. Implement Workers of Am., Int’l Union","cite":"523 U.S. 653","y":1998,"id":"1997/97-463","sc":1,"by":{"2":"28"},"q":[{"src":"brief","b":2,"text":"the meaning of a word cannot be determined in isolation, but must be drawn from the context in which it is used.","cite":"523 U.S. 653, 657"}]},{"t":"case","label":"United States v. Candelaria","cite":"271 U.S. 432","y":1926,"id":"scdb/1925-132","sc":1,"by":{"2":"6-7"}},{"t":"case","label":"United States v. Hagen","cite":"951 F.2d 261","y":1991,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/951/261/","by":{"2":"29","3":"16"}},{"t":"case","label":"Cases (ctd.): United States v. Riverside Bayview Homes, Inc.","cite":"474 U.S. 121","y":1985,"id":"1985/84-701","sc":1,"by":{"2":"44, 45","3":"19, 20"},"q":[{"src":"brief","b":2,"text":"construction has been brought to Congress’ attention through legislation specifically designed to supplant it,","cite":"474 U.S. 121, 137"},{"src":"brief","b":3,"text":"some evidence of the reasonableness of that construction.","cite":"474 U.S. 121, 137"}]},{"t":"case","label":"United States v. Rutherford","cite":"442 U.S. 544","y":1979,"id":"1978/78-605","sc":1,"by":{"2":"45","3":"20"},"q":[{"src":"brief","b":3,"text":"amended the [relevant] statute in other respects.","cite":"442 U.S. 544, 554 n.10"}]},{"t":"case","label":"United States v. Sandoval","cite":"231 U.S. 28","y":1913,"id":"scdb/1913-059","sc":1,"by":{"2":"7"}},{"t":"case","label":"United States v. Stewart","cite":"205 F.3d 840","y":2000,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/205/840/","by":{"2":"29","3":"16"},"q":[{"src":"brief","b":2,"text":"[t]o narrow the reach of that statute.","cite":"205 F.3d 840, 843"}]},{"t":"case","label":"United States v. Ward","cite":"448 U.S. 242","y":1980,"id":"1979/79-394","sc":1,"by":{"2":"22"}},{"t":"case","label":"Visa Inc. v. Osborn","cite":"137 S. Ct. 289","y":2016,"id":"2016/15-961","sc":1,"by":{"2":"33"}},{"t":"case","label":"Zipes v. Trans World Airlines, Inc.","cite":"455 U.S. 385","y":1983,"id":"1981/78-1545","sc":1,"by":{"2":"39"},"q":[{"src":"brief","b":2,"text":"refer in any way to the jurisdiction of the district courts.","cite":"455 U.S. 385, 394"}]},{"t":"const","label":"Article III, Section 47","by":{"2":"5"}},{"t":"const","label":"Article IV, Section 22","by":{"2":"8"}},{"t":"usc","label":"18 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/18/1153","by":{"2":"9"}},{"t":"usc","label":"31 U.S.C. § 3730","url":"https://www.law.cornell.edu/uscode/text/31/3730","subs":["(b)"],"by":{"2":"39"}},{"t":"usc","label":"33 U.S.C. § 1365","url":"https://www.law.cornell.edu/uscode/text/33/1365","by":{"2":"39"}},{"t":"usc","label":"42 U.S.C. § 7604","url":"https://www.law.cornell.edu/uscode/text/42/7604","by":{"2":"39"}},{"t":"reg","label":"78 Fed. Reg. 37,998","url":"https://www.govinfo.gov/link/fr/78/37998","by":{"2":"46"}},{"t":"case","label":"Cross-Petition for Writ of Certiorari, Texas v. Ysleta del Sur Pueblo","cite":"1995 WL 17048828","y":1995,"court":"U.S.","by":{"2":"36"},"q":[{"src":"brief","b":2,"text":"govern[ed] the substantive question regarding which gaming activities were allowed","cite":"1995 WL 17048828"}]},{"t":"case","label":"Petition for Writ of Certiorari, Ashcroft v. Seneca-Cayuga Tribe of Ok.","cite":"2003 WL 22873066","y":2004,"court":"U.S.","by":{"2":"31"}},{"t":"case","label":"Cottage Sav. Ass’n v. Comm’r","cite":"499 U.S. 554","y":1991,"id":"1990/89-1965","sc":1,"by":{"3":"3"}},{"t":"case","label":"Doe v. Chao","cite":"540 U.S. 614","y":2004,"id":"2003/02-1377","sc":1,"by":{"3":"11"}},{"t":"case","label":"N. Star Steel Co. v. Thomas","cite":"515 U.S. 29","y":1995,"id":"1994/94-834","sc":1,"by":{"3":"3"}},{"t":"case","label":"Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"by":{"3":"19"},"q":[{"src":"brief","b":3,"text":"[w]hat [Texas] refers to as ‘Congress’ deliberate acquiescence’ should more appropriately be called Congress’s failure to express any opinion,","cite":"547 U.S. 715, 750"}]},{"t":"case","label":"Smith v. United States","cite":"507 U.S. 197","y":1993,"id":"1992/91-1538","sc":1,"by":{"3":"11"}},{"t":"case","label":"Solid Waste Agency of N. Cook Cnty. v. U.S. Army Corps of Eng’rs","cite":"531 U.S. 159","y":2001,"id":"2000/99-1178","sc":1,"by":{"3":"19, 20"},"q":[{"src":"brief","b":3,"text":"A bill can be proposed for any number of reasons, and it can be rejected for just as many others.","cite":"531 U.S. 159, 170"},{"src":"brief","b":3,"text":"overcom[e] the plain text and import","cite":"531 U.S. at 169"}]},{"t":"case","label":"Star Athletica, L.L.C. v. Varsity Brands, Inc.","cite":"137 S. Ct. 1002","y":2017,"id":"2016/15-866","sc":1,"by":{"3":"4"}},{"t":"case","label":"Texas v. Alabama-Coushatta Tribe of Tex.","cite":"2021 WL 3884172","y":2021,"court":"E.D. Tex. Aug. 31","by":{"3":"23, 24"},"q":[{"src":"brief","b":3,"text":"a specific game of chance, commonly known as bingo or lotto, in which prizes are awarded on the basis of designated numbers or symbols conforming to randomly selected numbers or symbols.","cite":"2021 WL 3884172"}]},{"t":"case","label":"United States v. Wells","cite":"519 U.S. 482","y":1997,"id":"1996/95-1228","sc":1,"by":{"3":"3"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 420","y":2000,"id":"1999/99-6615","sc":1,"by":{"3":"3"},"q":[{"src":"brief","b":3,"text":"When the words of the Court are used in a later statute governing the same subject matter, it is respectful of Congress and of the Court’s own processes to give the words the same meaning in the absence of specific direction to the contrary.","cite":"529 U.S. 420, 434"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"[w]hen the words of the Court are used in a later statute governing the same subject matter, it is respectful of Congress and of the Court's own processes to give the words the same meaning in the absence of specifc direction to the contrary.","cite":"529 U. S. 420, 434"},{"src":"argument","who":"Mr. Martin","text":"Your Honor, first of all, I -- I think that under Williams versus Taylor, we certainly can assume that Congress was taking language from one of this Court's opinions and incorporating it, especially in the exact same context of Indian gaming, and that they knew what it meant."},{"src":"argument","who":"Mr. Yang","text":"And I would remind -- I would point to Williams versus Taylor, which -- a unanimous decision of this Court which said that when a later statute on the same subject matter uses words of a prior Supreme Court opinion, those words are given the same meaning unless there's a specific -- specific direction to the contrary."}]},{"t":"usc","label":"25 U.S.C. § 5396","url":"https://www.law.cornell.edu/uscode/text/25/5396","subs":["(b)"],"stext":{"head":"§5396. Application of other sections of this chapter","paras":[[0,"(a) Mandatory application"],[0,"All provisions of sections 5305(b), 5306, 5307, 5321(c) and (d), 5323, 5324(k) and (l), 5325(a) through (k), and 5332 of this title and section 314 of Public Law 101–512 (coverage under chapter 171 of title 28, commonly known as the \"Federal Tort Claims Act\"), to the extent not in conflict with this subchapter, shall apply to compacts and funding agreements authorized by this subchapter."],[0,"(b) Discretionary application"],[0,"At the request of a participating Indian tribe, any other provision of subchapter I of this chapter, to the extent such provision is not in conflict with this subchapter, shall be made a part of a funding agreement or compact entered into under this subchapter. The Secretary is obligated to include such provision at the option of the participating Indian tribe or tribes. If such provision is incorporated it shall have the same force and effect as if it were set out in full in this subchapter. In the event an Indian tribe requests such incorporation at the negotiation stage of a compact or funding agreement, such incorporation shall be deemed effective immediately and shall control the negotiation and resulting compact and funding agreement."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5396?type=usc&year=mostrecent&link-type=html"},"by":{"3":"8"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"shall have the same force and effect as if it were set out in full in this subchapter.","cite":"25 U. S. C. § 5396(b)"}]}]};